"use strict";
// A weight written as text answers grams; a number of grams answers a label.
var UNITS = { g: 1, kg: 1000, t: 1000000 };

function grams(text) {
  var found = /^(-?\d*\.?\d+) *(g|kg|t)?$/.exec(text);
  if (!found) {
    return;
  }
  return parseFloat(found[1]) * UNITS[found[2] || "g"];
}

function label(amount, long) {
  if (Math.abs(amount) >= UNITS.kg) {
    return amount / UNITS.kg + (long ? " kilograms" : "kg");
  }
  return amount + (long ? " grams" : "g");
}

module.exports = function (value, options) {
  options = options || {};
  if (typeof value === "string" && value.length > 0) {
    return grams(value);
  } else if (typeof value === "number" && isFinite(value)) {
    return label(value, options.long);
  }
  throw new Error("weigh: expected a weight or a number of grams, got " + JSON.stringify(value));
};
